const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region: Lower Mississippi River (Mississippi and Louisiana)
  const region = ee.Geometry.Rectangle([-92.5, 29.0, -89.0, 33.0]);

  // 2. Date ranges (±7 days for image availability)
  const date1Start = '2019-11-27';
  const date1End = '2019-12-11';
  const date2Start = '2020-01-26';
  const date2End = '2020-02-09';

  // 3. Load Sentinel-1 SAR data (better for water detection, cloud-independent)
  let col1 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(region)
    .filterDate(date1Start, date1End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  let col2 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(region)
    .filterDate(date2Start, date2End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Dec 2019 Images: ${size1}`);
  console.log(`Feb 2020 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Insufficient data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Create median composites and detect water (VV < -15 dB typically indicates water)
  const img1 = col1.median();
  const img2 = col2.median();

  const waterThreshold = -15;
  const water1 = img1.lt(waterThreshold);
  const water2 = img2.lt(waterThreshold);

  // 5. Calculate water area in square meters
  const pixelArea = ee.Image.pixelArea();

  const area1Result = water1.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const area2Result = water2.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  // 6. Check pixel counts
  const count1Result = water1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const count1 = count1Result.get('VV').getInfo();

  if (count1 === 0 || count1 === null) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  const area1 = area1Result.get('VV').getInfo();
  const area2 = area2Result.get('VV').getInfo();

  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  const area1_km2 = area1 / 1e6;
  const area2_km2 = area2 / 1e6;
  const change = area2_km2 - area1_km2;
  const percentChange = ((change / area1_km2) * 100).toFixed(1);

  console.log(`Dec 2019 Water: ${area1_km2.toFixed(2)} km²`);
  console.log(`Feb 2020 Water: ${area2_km2.toFixed(2)} km²`);
  console.log(`Change: ${change.toFixed(2)} km² (${percentChange}%)`);
  console.log(`Valid Pixels: ${count1}`);

  if (area2 > area1) {
    console.log("Water extent INCREASED in February 2020.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent DID NOT increase in February 2020.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
